import sys
sys.path.insert(0,'/Users/regan/Dev/Renesas_SH0755_modding/tests');import _test_paths
from test_timing_feedback_process_flow import TimingFeedbackMachine,RAM,ROOT
from test_startup_retained_process_flow import StartupRetainedMachine,BANK_WRITES
from test_opening_timing_execution import LIMIT_WRITES
class Temp(TimingFeedbackMachine):
 call_lookup=StartupRetainedMachine.call_lookup
 def __init__(self,image,rpm=2800,coolant=67):
  self.native_targets=set();super().__init__(image,rpm=rpm,speed=44,coolant=coolant,correction=0);self.final_inputs()
  self.write(RAM+0xB484,0,1);self.write(RAM+0xB51C,1,1);self.write(RAM+0xB51A,0,1);self.write(RAM+0xB51D,0,1);self.write(RAM+0xCD48,4,1)
  for a,v in [(0xB3B8,37),(0xB438,2),(0xB2F4,10),(0xB2F8,20),(0xB314,80),(0xC104,-10)]:self.put_float(RAM+a,v)
  self.write(RAM+0xC12A,0,1);self.write(RAM+0xC121,1,1);self.write(RAM+0xC12E,7,1);self.write(RAM+0xC128,0,2)
 def hot(self):
  for e in (0x27480,0x2769C,0x27728,0x2777C):self.execute(e,BANK_WRITES)
  return [self.read(RAM+0xC121,1),self.read(RAM+0xC12E,1),self.read(RAM+0xC128,2),self.get_float(RAM+0xC108),self.get_float(RAM+0xC104),self.final()]
if __name__=='__main__':
 im=(ROOT/'master_patch_v2/D2WD610H_master_patch_v2.bin').read_bytes()
 for ect,rpm in [(67,2800),(120,2000)]:
  c=Temp(im,rpm,ect)
  try:
   for i in range(20):
    out=c.hot()
    if i in [0,1,15,17,18,19]:print(ect,rpm,i,out)
  except Exception as e:print('failed',hex(c.pc),e)

